import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock providers - the Foundation must control its variables
const mockCartContext = {
  items: [{ id: '1', name: 'Primer', price: 29.99 }],
  total: 29.99,
  clearCart: vi.fn(),
};

const mockPaymentContext = {
  processPayment: vi.fn(),
};

vi.mock('./CartContext', () => ({
  useCart: () => mockCartContext,
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => mockPaymentContext,
}));

describe('Checkout - The Seldon Plan', () => {
  const user = userEvent.setup();

  beforeEach(() => {
    vi.clearAllMocks();
    mockCartContext.items = [{ id: '1', name: 'Primer', price: 29.99 }];
    mockPaymentContext.processPayment.mockResolvedValue({ orderId: 'ORD-12345' });
  });

  describe('Happy Path - Mathematical Certainty', () => {
    it('completes full checkout flow from shipping to confirmation', async () => {
      const onComplete = vi.fn();
      render(<Checkout onComplete={onComplete} />);

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), '123 Foundation Way');
      await user.type(screen.getByLabelText(/city/i), 'Terminus');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Hari Seldon');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByText(/123 Foundation Way/)).toBeInTheDocument();
      expect(screen.getByText(/ending in 1111/)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      expect(await screen.findByText(/order confirmed/i)).toBeInTheDocument();
      expect(screen.getByText('ORD-12345')).toBeInTheDocument();
      expect(onComplete).toHaveBeenCalledWith('ORD-12345');
    });
  });

  describe('Form Validation - Deviations from the Plan', () => {
    it('displays error when street address is empty', async () => {
      render(<Checkout />);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/street address is required/i);
      expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('validates ZIP code format', async () => {
      render(<Checkout />);
      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });

    it('validates card number is 16 digits', async () => {
      render(<Checkout />);
      // Navigate to payment
      await user.type(screen.getByLabelText(/street/i), '123 Test');
      await user.type(screen.getByLabelText(/city/i), 'City');
      await user.selectOptions(screen.getByLabelText(/state/i), 'NY');
      await user.type(screen.getByLabelText(/zip/i), '10001');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      await user.type(screen.getByLabelText(/card number/i), '123');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      expect(screen.getByText(/valid 16-digit card number required/i)).toBeInTheDocument();
    });
  });

  describe('Error States - Seldon Crises', () => {
    it('displays payment error and allows retry', async () => {
      mockPaymentContext.processPayment.mockRejectedValueOnce(new Error('Card declined'));
      render(<Checkout />);

      // Complete shipping and payment forms...
      // (abbreviated for space)

      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(await screen.findByRole('alert')).toHaveTextContent(/card declined/i);
      expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
    });
  });

  describe('Loading States', () => {
    it('disables buttons and shows loading text during submission', async () => {
      mockPaymentContext.processPayment.mockImplementation(
        () => new Promise((resolve) => setTimeout(resolve, 100))
      );
      render(<Checkout />);
      // Navigate to review step...

      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
      expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
    });
  });

  describe('Edge Cases - Individual Deviations', () => {
    it('shows empty cart message when no items', () => {
      mockCartContext.items = [];
      const onCancel = vi.fn();
      render(<Checkout onCancel={onCancel} />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
      await user.click(screen.getByRole('button', { name: /continue shopping/i }));
      expect(onCancel).toHaveBeenCalled();
    });
  });

  describe('Accessibility - Universal Design', () => {
    it('has no accessibility violations', async () => {
      const { container } = render(<Checkout />);
      const results = await axe(container);
      expect(results).toHaveNoViolations();
    });

    it('maintains focus management between steps', async () => {
      render(<Checkout />);
      // Progress indicator announces current step
      expect(screen.getByRole('listitem', { current: 'step' })).toHaveTextContent(/shipping/i);
    });
  });
});
